-- ============================================================================
--  Family Learn - French + ICT for Omar (Primary 6) and Yassin (Primary 3)
--  (GENERATED by content/build_fr_ict.py from content/t1/fr3.py, fr6.py, ict3.py, ict6.py,
--   content/fr_ict_schema.sql and content/fr_ict_functions.sql).
--  4 courses, 15 units, 60 lessons, 340 questions.
--  Only touches these courses: 'fr-g3', 'ict-g3', 'fr-g6', 'ict-g6' (plus the source label of the existing book courses).
--  Safe to run more than once. Nothing is deleted; progress is kept.
-- ============================================================================
begin;
-- ---------------------------------------------------------------- schema (French + ICT, 0014)
-- New subject 'french' ('ict' is already allowed since 0012).
alter table public.courses drop constraint if exists courses_subject_check;
alter table public.courses add constraint courses_subject_check
  check (subject in ('english', 'math', 'business', 'arabic', 'religion', 'social', 'science', 'ict', 'french'));

-- Where the content comes from (shown to the parent / editor and as a note on the course page):
--   official      = lessons and questions built from the MoE school book pages
--   book_topics   = the book's lesson list, but the explanations / questions are written by the app
--   supplementary = extra path written by the app (not from an MoE book)
alter table public.courses add column if not exists source_kind  text;
alter table public.courses add column if not exists source_note  text;
alter table public.courses add column if not exists edition      text;
alter table public.courses add column if not exists speech_lang  text;   -- e.g. fr-FR: language of the 🔊 buttons
alter table public.courses drop constraint if exists courses_source_kind_check;
alter table public.courses add constraint courses_source_kind_check
  check (source_kind is null or source_kind in ('official', 'book_topics', 'supplementary'));

-- Lesson explanation shown before the exercises:
--   {"goals": [...], "explain": "...", "vocab": [{"w","ar","say"}], "examples": [...], "activity": "...", "summary": "..."}
alter table public.lessons add column if not exists intro jsonb;

-- The courses already built from the MoE book pages (0005 Term 2, 0012 Term 1). Only set when empty.
update public.courses
   set source_kind = 'official',
       source_note = coalesce(source_note, 'من صفحات كتاب الوزارة (مدارس اللغات). الأسئلة تدريبية من إعداد التطبيق على دروس الكتاب.'),
       edition     = coalesce(edition, case when id like '%-t1' or id in ('ar-g3', 'ar-g6', 'isl-g3', 'isl-g6', 'soc-g6')
                                            then '2026/2027 — الترم الأول' else 'الترم الثاني' end)
 where source_kind is null
   and id in ('eng-g3', 'math-g3', 'eng-g6', 'math-g6',
              'eng-g3-t1', 'ar-g3', 'isl-g3', 'eng-g6-t1', 'math-g6-t1', 'ar-g6', 'isl-g6', 'soc-g6');

-- ---------------------------------------------------------------- content
insert into public.skills (code, name, subject)
select code, name, subject from jsonb_to_recordset('[{"code":"fr3.greet","name":"التحية والتعارف","subject":"fr3"},{"code":"fr3.feel","name":"ça va ? — السؤال عن الحال","subject":"fr3"},{"code":"fr3.class","name":"أدوات المدرسة","subject":"fr3"},{"code":"fr3.gender","name":"un / une — المذكر والمؤنث","subject":"fr3"},{"code":"fr3.colour","name":"الألوان","subject":"fr3"},{"code":"fr3.num","name":"الأعداد","subject":"fr3"},{"code":"fr3.age","name":"العمر — J''ai ... ans","subject":"fr3"},{"code":"fr3.family","name":"العائلة","subject":"fr3"},{"code":"fr3.poss","name":"mon / ma","subject":"fr3"},{"code":"fr3.days","name":"أيام الأسبوع","subject":"fr3"},{"code":"fr3.listen","name":"الاستماع","subject":"fr3"},{"code":"fr3.read","name":"القراءة","subject":"fr3"},{"code":"ict3.parts","name":"Computer parts","subject":"ict3"},{"code":"ict3.io","name":"Input and output devices","subject":"ict3"},{"code":"ict3.mouse","name":"Using the mouse","subject":"ict3"},{"code":"ict3.keys","name":"Using the keyboard","subject":"ict3"},{"code":"ict3.devices","name":"Digital devices","subject":"ict3"},{"code":"ict3.care","name":"Using devices well","subject":"ict3"},{"code":"ict3.safe","name":"Staying safe online","subject":"ict3"},{"code":"ict3.kind","name":"Being kind online","subject":"ict3"},{"code":"ict3.algo","name":"Steps and order (algorithms)","subject":"ict3"},{"code":"ict3.loop","name":"Repeat (loops)","subject":"ict3"},{"code":"ict3.debug","name":"Finding mistakes (debugging)","subject":"ict3"},{"code":"fr6.intro","name":"التعريف بالنفس","subject":"fr6"},{"code":"fr6.etre","name":"فعل être (يكون)","subject":"fr6"},{"code":"fr6.avoir","name":"فعل avoir (يملك)","subject":"fr6"},{"code":"fr6.time","name":"الساعة والوقت","subject":"fr6"},{"code":"fr6.er","name":"أفعال -er في المضارع","subject":"fr6"},{"code":"fr6.subj","name":"المواد الدراسية","subject":"fr6"},{"code":"fr6.like","name":"aimer / préférer — التعبير عن الحب","subject":"fr6"},{"code":"fr6.neg","name":"النفي ne … pas","subject":"fr6"},{"code":"fr6.place","name":"أماكن المدينة","subject":"fr6"},{"code":"fr6.prep","name":"حروف الجر المكانية","subject":"fr6"},{"code":"fr6.aller","name":"فعل aller + au / à la","subject":"fr6"},{"code":"fr6.hobby","name":"الهوايات والطعام","subject":"fr6"},{"code":"fr6.question","name":"طرح الأسئلة","subject":"fr6"},{"code":"fr6.listen","name":"الاستماع","subject":"fr6"},{"code":"fr6.read","name":"القراءة","subject":"fr6"},{"code":"ict6.network","name":"Computer networks","subject":"ict6"},{"code":"ict6.future","name":"Future technology","subject":"ict6"},{"code":"ict6.access","name":"Technology for people with special needs","subject":"ict6"},{"code":"ict6.search","name":"Digital search tools","subject":"ict6"},{"code":"ict6.os","name":"Operating systems","subject":"ict6"},{"code":"ict6.web","name":"Web design","subject":"ict6"},{"code":"ict6.games","name":"Video games: fun and safety","subject":"ict6"},{"code":"ict6.data","name":"Protecting my digital data","subject":"ict6"},{"code":"ict6.cyber","name":"Cyber security","subject":"ict6"},{"code":"ict6.money","name":"Online buying, selling and payment","subject":"ict6"},{"code":"ict6.cloud","name":"Cloud computing and storage","subject":"ict6"},{"code":"ict6.terms","name":"ICT terms","subject":"ict6"}]'::jsonb) as x(code text, name text, subject text)
on conflict (code) do update set name = excluded.name, subject = excluded.subject;

insert into public.courses (id, subject, title, level_label, audience, grade_min, grade_max, position,
                            source_kind, source_note, edition, speech_lang)
select id, subject, title, level_label, audience, grade_min, grade_max, position, source_kind, source_note, edition, speech_lang
  from jsonb_to_recordset('[{"id":"fr-g3","subject":"french","title":"🇫🇷 French Language — اللغة الفرنسية","level_label":"Primary 3 · مسار إضافي","audience":"child","grade_min":3,"grade_max":3,"position":26,"source_kind":"supplementary","source_note":"مسار إضافي من إعداد التطبيق للمبتدئين (الصف الثالث). لم يُعثر على كتاب وزارة رسمي للفرنسية في الصف الثالث؛ مدارس اللغات تختار كتابها. أرسل صفحات كتاب الفرنسية الخاص بالمدرسة ليُبنى المسار منه.","edition":"2026/2027","speech_lang":"fr-FR"},{"id":"ict-g3","subject":"ict","title":"💻 ICT — Information and Communication Technology","level_label":"Primary 3 · مسار إضافي","audience":"child","grade_min":3,"grade_max":3,"position":27,"source_kind":"supplementary","source_note":"مسار إضافي من إعداد التطبيق. مادة ICT في المنهج المصري (التعليم 2.0) تبدأ من الصف الرابع الابتدائي، ولم يُعثر على كتاب وزارة ICT للصف الثالث. المسار تمهيدي: الحاسب ومكوناته، الأمان على الإنترنت، والتفكير البرمجي.","edition":"2026/2027","speech_lang":"en-US"},{"id":"fr-g6","subject":"french","title":"🇫🇷 French Language — اللغة الفرنسية","level_label":"Primary 6 · مسار إضافي","audience":"child","grade_min":6,"grade_max":6,"position":35,"source_kind":"supplementary","source_note":"مسار إضافي من إعداد التطبيق بمستوى A1 (الصف السادس). لم يُعثر على كتاب وزارة رسمي للفرنسية في الصف السادس؛ مدارس اللغات تختار كتابها. أرسل صفحات كتاب الفرنسية الخاص بالمدرسة ليُبنى المسار منه.","edition":"2026/2027","speech_lang":"fr-FR"},{"id":"ict-g6","subject":"ict","title":"💻 ICT — Information and Communication Technology","level_label":"Primary 6 · Term 1","audience":"child","grade_min":6,"grade_max":6,"position":36,"source_kind":"book_topics","source_note":"عناوين الدروس مطابقة لدروس الترم الأول في كتاب ICT للصف السادس (لغات) كما تعرضها منصة Nagwa للمنهج المصري. صفحات كتاب الوزارة لم تُقرأ (موقع مكتبة الوزارة رفض الوصول)، فالشرح والأسئلة من إعداد التطبيق وتحتاج مراجعة على الكتاب.","edition":"2026/2027 — الترم الأول","speech_lang":"en-US"}]'::jsonb)
    as x(id text, subject text, title text, level_label text, audience text, grade_min smallint, grade_max smallint,
         position smallint, source_kind text, source_note text, edition text, speech_lang text)
on conflict (id) do update set subject = excluded.subject, title = excluded.title, level_label = excluded.level_label,
  audience = excluded.audience, grade_min = excluded.grade_min, grade_max = excluded.grade_max, position = excluded.position,
  source_kind = excluded.source_kind, source_note = excluded.source_note, edition = excluded.edition,
  speech_lang = excluded.speech_lang;

insert into public.units (id, course_id, position, title)
select id, course_id, position, title from jsonb_to_recordset('[{"id":"fr-g3.u1","course_id":"fr-g3","position":1,"title":"Bonjour ! — التحية"},{"id":"fr-g3.u2","course_id":"fr-g3","position":2,"title":"À l''école — في المدرسة"},{"id":"fr-g3.u3","course_id":"fr-g3","position":3,"title":"Les nombres — الأعداد"},{"id":"fr-g3.u4","course_id":"fr-g3","position":4,"title":"Ma famille — عائلتي"},{"id":"ict-g3.u1","course_id":"ict-g3","position":1,"title":"My computer — جهازي"},{"id":"ict-g3.u2","course_id":"ict-g3","position":2,"title":"Devices around us — أجهزة حولنا"},{"id":"ict-g3.u3","course_id":"ict-g3","position":3,"title":"Safe online — آمن على الإنترنت"},{"id":"ict-g3.u4","course_id":"ict-g3","position":4,"title":"Think like a programmer — أفكر كمبرمج"},{"id":"fr-g6.u1","course_id":"fr-g6","position":1,"title":"Je me présente — أعرّف بنفسي"},{"id":"fr-g6.u2","course_id":"fr-g6","position":2,"title":"Ma journée — يومي"},{"id":"fr-g6.u3","course_id":"fr-g6","position":3,"title":"À l''école — في المدرسة"},{"id":"fr-g6.u4","course_id":"fr-g6","position":4,"title":"Dans ma ville — في مدينتي"},{"id":"fr-g6.u5","course_id":"fr-g6","position":5,"title":"Mes loisirs — هواياتي"},{"id":"ict-g6.u1","course_id":"ict-g6","position":1,"title":"Technology in our lives — التكنولوجيا في حياتنا"},{"id":"ict-g6.u2","course_id":"ict-g6","position":2,"title":"Safe in the digital world — الأمان في العالم الرقمي"}]'::jsonb) as x(id text, course_id text, position smallint, title text)
on conflict (id) do update set course_id = excluded.course_id, position = excluded.position, title = excluded.title, archived = false;

update public.lessons set position = position + 1000 where course_id in ('fr-g3', 'ict-g3', 'fr-g6', 'ict-g6') and not archived;
insert into public.lessons (id, unit_id, course_id, position, title, minutes, intro)
select id, unit_id, course_id, position, title, minutes, intro
  from jsonb_to_recordset('[{"id":"fr-g3.u1.l1","unit_id":"fr-g3.u1","course_id":"fr-g3","position":1,"title":"Bonjour, au revoir — مرحبًا ومع السلامة","minutes":7,"intro":{"goals":["أقول مرحبًا ومع السلامة بالفرنسية","أعرف متى أقول Bonjour ومتى أقول Bonsoir"],"explain":"في الفرنسية نقول Bonjour في الصباح والنهار، وBonsoir في المساء. Salut تحية بين الأصدقاء. وعند الذهاب نقول Au revoir.","vocab":[{"w":"Bonjour","ar":"صباح الخير / مرحبًا","say":"بونْجُور"},{"w":"Bonsoir","ar":"مساء الخير","say":"بونْسْوار"},{"w":"Salut","ar":"أهلًا (للأصدقاء)","say":"سالُو"},{"w":"Au revoir","ar":"مع السلامة","say":"أُو رِڤْوار"},{"w":"Merci","ar":"شكرًا","say":"مِرْسِي"}],"examples":["Bonjour, madame !","Au revoir, Yassin !"],"summary":"Bonjour = نهارًا · Bonsoir = مساءً · Au revoir = عند الذهاب · Merci = شكرًا"}},{"id":"fr-g3.u1.l2","unit_id":"fr-g3.u1","course_id":"fr-g3","position":2,"title":"Je m''appelle… — اسمي…","minutes":7,"intro":{"goals":["أعرّف بنفسي: Je m''appelle …","أسأل عن الاسم: Tu t''appelles comment ?"],"explain":"لنقول «اسمي ياسين» نقول: Je m''appelle Yassin. ولنسأل صديقنا عن اسمه نقول: Tu t''appelles comment ?","vocab":[{"w":"Je m''appelle Yassin.","ar":"اسمي ياسين.","say":"جُو مابِلْ ياسين"},{"w":"Tu t''appelles comment ?","ar":"ما اسمك؟","say":"تُو تابِلْ كومون؟"},{"w":"Enchanté","ar":"تشرفت بمعرفتك","say":"أونْشونْتيه"},{"w":"Moi","ar":"أنا","say":"مْوا"}],"examples":["— Tu t''appelles comment ?  — Je m''appelle Omar."],"summary":"Je m''appelle … = اسمي … · Tu t''appelles comment ? = ما اسمك؟"}},{"id":"fr-g3.u1.l3","unit_id":"fr-g3.u1","course_id":"fr-g3","position":3,"title":"Ça va ? — كيف حالك؟","minutes":7,"intro":{"goals":["أسأل عن الحال وأجيب"],"explain":"نسأل: Ça va ? (كيف حالك؟). نجيب: Ça va bien, merci ! (بخير، شكرًا). وإذا لم نكن بخير نقول: Ça ne va pas.","vocab":[{"w":"Ça va ?","ar":"كيف حالك؟","say":"سا ڤا؟"},{"w":"Ça va bien","ar":"أنا بخير","say":"سا ڤا بْيان"},{"w":"Très bien","ar":"جيد جدًا","say":"تْريه بْيان"},{"w":"Ça ne va pas","ar":"لستُ بخير","say":"سا نُو ڤا پا"},{"w":"Et toi ?","ar":"وأنت؟","say":"إيه تْوا؟"}],"examples":["— Ça va ?  — Très bien, merci ! Et toi ?"],"summary":"Ça va ? ← Ça va bien / Très bien / Ça ne va pas"}},{"id":"fr-g3.u1.l4","unit_id":"fr-g3.u1","course_id":"fr-g3","position":4,"title":"مراجعة الوحدة 1 — Bonjour !","minutes":8,"intro":{"summary":"راجع: Bonjour · Bonsoir · Salut · Au revoir · Merci · Je m''appelle … · Ça va ?"}},{"id":"fr-g3.u2.l1","unit_id":"fr-g3.u2","course_id":"fr-g3","position":5,"title":"Ma trousse — أدواتي","minutes":8,"intro":{"goals":["أسمّي أدوات المدرسة بالفرنسية"],"explain":"أدوات المدرسة لها أسماء بالفرنسية، وقبل كل اسم كلمة صغيرة: un أو une (تعني «واحد/واحدة»).","vocab":[{"w":"un crayon","ar":"قلم رصاص","say":"أَن كْرِيُون"},{"w":"un stylo","ar":"قلم حبر","say":"أَن سْتِيلو"},{"w":"une gomme","ar":"ممحاة","say":"يُون جوم"},{"w":"une règle","ar":"مسطرة","say":"يُون رِيجْل"},{"w":"un cahier","ar":"كراسة","say":"أَن كايِيه"},{"w":"un livre","ar":"كتاب","say":"أَن لِيڤْر"},{"w":"une trousse","ar":"مقلمة","say":"يُون تْرُوس"},{"w":"un cartable","ar":"حقيبة المدرسة","say":"أَن كارْتابْل"}],"summary":"crayon قلم رصاص · stylo قلم · gomme ممحاة · règle مسطرة · cahier كراسة · livre كتاب"}},{"id":"fr-g3.u2.l2","unit_id":"fr-g3.u2","course_id":"fr-g3","position":6,"title":"Un ou une ? — مذكر أم مؤنث","minutes":8,"intro":{"goals":["أعرف أن الأسماء في الفرنسية مذكرة أو مؤنثة","أستخدم un مع المذكر وune مع المؤنث"],"explain":"في الفرنسية كل اسم إمّا مذكر (masculin) أو مؤنث (féminin). نستخدم un مع المذكر: un livre، ونستخدم une مع المؤنث: une gomme. نحفظ الكلمة دائمًا مع un أو une.","vocab":[{"w":"un livre","ar":"مذكر","say":"أَن لِيڤْر"},{"w":"une gomme","ar":"مؤنث","say":"يُون جوم"},{"w":"un garçon","ar":"ولد","say":"أَن جارْسون"},{"w":"une fille","ar":"بنت","say":"يُون فِيي"}],"summary":"un + مذكر · une + مؤنث"}},{"id":"fr-g3.u2.l3","unit_id":"fr-g3.u2","course_id":"fr-g3","position":7,"title":"Les couleurs — الألوان","minutes":8,"intro":{"goals":["أسمّي الألوان بالفرنسية","أسأل: C''est de quelle couleur ?"],"explain":"نسأل عن اللون: C''est de quelle couleur ? ونجيب: C''est rouge. (إنه أحمر)","vocab":[{"w":"rouge","ar":"أحمر 🔴","say":"روج"},{"w":"bleu","ar":"أزرق 🔵","say":"بْلُو"},{"w":"vert","ar":"أخضر 🟢","say":"ڤِير"},{"w":"jaune","ar":"أصفر 🟡","say":"جون"},{"w":"noir","ar":"أسود ⚫","say":"نْوار"},{"w":"blanc","ar":"أبيض ⚪","say":"بْلون"},{"w":"orange","ar":"برتقالي 🟠","say":"أورونْج"}],"summary":"rouge · bleu · vert · jaune · noir · blanc · orange"}},{"id":"fr-g3.u2.l4","unit_id":"fr-g3.u2","course_id":"fr-g3","position":8,"title":"مراجعة الوحدة 2 — À l''école","minutes":8,"intro":{"summary":"راجع: أدوات المدرسة · un / une · الألوان"}},{"id":"fr-g3.u3.l1","unit_id":"fr-g3.u3","course_id":"fr-g3","position":9,"title":"Les nombres de 0 à 10","minutes":8,"intro":{"goals":["أعدّ من 0 إلى 10 بالفرنسية"],"explain":"تعلّم الأعداد واسمعها جيدًا، ثم حاول نطقها.","vocab":[{"w":"zéro","ar":"0","say":"زِيرو"},{"w":"un","ar":"1","say":"أَن"},{"w":"deux","ar":"2","say":"دُو"},{"w":"trois","ar":"3","say":"تْروا"},{"w":"quatre","ar":"4","say":"كاتْر"},{"w":"cinq","ar":"5","say":"سانْك"},{"w":"six","ar":"6","say":"سِيس"},{"w":"sept","ar":"7","say":"سِيت"},{"w":"huit","ar":"8","say":"وِيت"},{"w":"neuf","ar":"9","say":"نُوف"},{"w":"dix","ar":"10","say":"دِيس"}],"summary":"0 zéro · 1 un · 2 deux · 3 trois · 4 quatre · 5 cinq · 6 six · 7 sept · 8 huit · 9 neuf · 10 dix"}},{"id":"fr-g3.u3.l2","unit_id":"fr-g3.u3","course_id":"fr-g3","position":10,"title":"Les nombres de 11 à 20","minutes":8,"intro":{"goals":["أعدّ من 11 إلى 20 بالفرنسية"],"vocab":[{"w":"onze","ar":"11","say":"أونْز"},{"w":"douze","ar":"12","say":"دُوز"},{"w":"treize","ar":"13","say":"تْرِيز"},{"w":"quatorze","ar":"14","say":"كاتورْز"},{"w":"quinze","ar":"15","say":"كانْز"},{"w":"seize","ar":"16","say":"سِيز"},{"w":"dix-sept","ar":"17","say":"دِي سِيت"},{"w":"dix-huit","ar":"18","say":"دِيز وِيت"},{"w":"dix-neuf","ar":"19","say":"دِيز نُوف"},{"w":"vingt","ar":"20","say":"ڤان"}],"explain":"من 17 إلى 19 نقول «عشرة + العدد»: dix-sept (10+7)، dix-huit (10+8)، dix-neuf (10+9).","summary":"17 = dix-sept · 18 = dix-huit · 19 = dix-neuf · 20 = vingt"}},{"id":"fr-g3.u3.l3","unit_id":"fr-g3.u3","course_id":"fr-g3","position":11,"title":"Quel âge as-tu ? — كم عمرك؟","minutes":7,"intro":{"goals":["أسأل عن العمر وأجيب"],"explain":"نسأل: Quel âge as-tu ? (كم عمرك؟). نجيب: J''ai neuf ans. (عمري تسع سنوات). ans تعني «سنوات».","vocab":[{"w":"Quel âge as-tu ?","ar":"كم عمرك؟","say":"كِيل آج آ تُو؟"},{"w":"J''ai neuf ans.","ar":"عمري 9 سنوات.","say":"جيه نُوڤ أون"},{"w":"J''ai huit ans.","ar":"عمري 8 سنوات.","say":"جيه وِيت أون"}],"summary":"Quel âge as-tu ? ← J''ai … ans."}},{"id":"fr-g3.u3.l4","unit_id":"fr-g3.u3","course_id":"fr-g3","position":12,"title":"مراجعة الوحدة 3 — Les nombres","minutes":8,"intro":{"summary":"راجع الأعداد 0–20 و Quel âge as-tu ?"}},{"id":"fr-g3.u4.l1","unit_id":"fr-g3.u4","course_id":"fr-g3","position":13,"title":"Ma famille — أفراد العائلة","minutes":8,"intro":{"goals":["أسمّي أفراد العائلة بالفرنسية"],"vocab":[{"w":"le père / papa","ar":"الأب / بابا","say":"لُو پِير / پاپا"},{"w":"la mère / maman","ar":"الأم / ماما","say":"لا مِير / مامان"},{"w":"le frère","ar":"الأخ","say":"لُو فْرير"},{"w":"la sœur","ar":"الأخت","say":"لا سُور"},{"w":"le grand-père","ar":"الجد","say":"لُو جْرون پِير"},{"w":"la grand-mère","ar":"الجدة","say":"لا جْرون مِير"},{"w":"la famille","ar":"العائلة","say":"لا فامِيي"}],"explain":"le قبل الاسم المذكر، وla قبل الاسم المؤنث (تعني «الـ» للتعريف).","summary":"le père · la mère · le frère · la sœur · le grand-père · la grand-mère"}},{"id":"fr-g3.u4.l2","unit_id":"fr-g3.u4","course_id":"fr-g3","position":14,"title":"Mon / ma — لي (مذكر / مؤنث)","minutes":8,"intro":{"goals":["أستخدم mon مع المذكر وma مع المؤنث"],"explain":"لنقول «أبي» نقول mon père (لأن père مذكر)، ولنقول «أمي» نقول ma mère (لأن mère مؤنثة). ونقدّم عائلتنا بـ: Voici … (هذا / هذه …).","vocab":[{"w":"mon père","ar":"أبي","say":"مون پِير"},{"w":"ma mère","ar":"أمي","say":"ما مِير"},{"w":"mon frère Omar","ar":"أخي عمر","say":"مون فْرير عمر"},{"w":"Voici ma sœur.","ar":"هذه أختي.","say":"ڤْواسي ما سُور"}],"summary":"mon + مذكر · ma + مؤنث · Voici = هذا / هذه"}},{"id":"fr-g3.u4.l3","unit_id":"fr-g3.u4","course_id":"fr-g3","position":15,"title":"Les jours de la semaine — أيام الأسبوع","minutes":8,"intro":{"goals":["أعرف أيام الأسبوع بالفرنسية بالترتيب"],"explain":"في الفرنسية يبدأ الأسبوع بيوم الاثنين lundi. أسماء الأيام تُكتب بحروف صغيرة.","vocab":[{"w":"lundi","ar":"الاثنين","say":"لانْدِي"},{"w":"mardi","ar":"الثلاثاء","say":"مارْدِي"},{"w":"mercredi","ar":"الأربعاء","say":"مِيرْكْرُودِي"},{"w":"jeudi","ar":"الخميس","say":"جُودِي"},{"w":"vendredi","ar":"الجمعة","say":"ڤونْدْرُودِي"},{"w":"samedi","ar":"السبت","say":"سامْدِي"},{"w":"dimanche","ar":"الأحد","say":"دِيمونْش"}],"summary":"lundi · mardi · mercredi · jeudi · vendredi · samedi · dimanche"}},{"id":"fr-g3.u4.l4","unit_id":"fr-g3.u4","course_id":"fr-g3","position":16,"title":"مراجعة الوحدة 4 — Ma famille","minutes":8,"intro":{"summary":"راجع: أفراد العائلة · mon / ma · أيام الأسبوع"}},{"id":"ict-g3.u1.l1","unit_id":"ict-g3.u1","course_id":"ict-g3","position":1,"title":"Parts of the computer — أجزاء الحاسب","minutes":7,"intro":{"goals":["أسمّي أجزاء الحاسب بالإنجليزية","أعرف وظيفة كل جزء"],"explain":"الحاسب له أجزاء: الشاشة Monitor نرى عليها الصور والكلام، لوحة المفاتيح Keyboard نكتب بها، الفأرة Mouse نحرّك بها السهم ونضغط، وصندوق الحاسب System unit فيه «عقل» الجهاز، والسماعات Speakers نسمع منها الصوت.","vocab":[{"w":"Monitor","ar":"الشاشة 🖥️"},{"w":"Keyboard","ar":"لوحة المفاتيح ⌨️"},{"w":"Mouse","ar":"الفأرة 🖱️"},{"w":"System unit","ar":"صندوق الحاسب"},{"w":"Speakers","ar":"السماعات 🔈"},{"w":"Printer","ar":"الطابعة 🖨️"}],"activity":"أشِر إلى كل جزء في حاسب البيت أو المدرسة وقل اسمه بالإنجليزية.","summary":"Monitor · Keyboard · Mouse · System unit · Speakers · Printer"}},{"id":"ict-g3.u1.l2","unit_id":"ict-g3.u1","course_id":"ict-g3","position":2,"title":"Input and output — إدخال وإخراج","minutes":8,"intro":{"goals":["أفرّق بين أجهزة الإدخال وأجهزة الإخراج"],"explain":"أجهزة الإدخال Input devices ندخل بها المعلومات إلى الحاسب: لوحة المفاتيح، الفأرة، الميكروفون، الكاميرا. أجهزة الإخراج Output devices يعطينا الحاسب النتيجة من خلالها: الشاشة، السماعات، الطابعة.","vocab":[{"w":"Input","ar":"إدخال: من المستخدم إلى الحاسب"},{"w":"Output","ar":"إخراج: من الحاسب إلى المستخدم"},{"w":"Microphone","ar":"الميكروفون 🎤 (إدخال)"},{"w":"Camera","ar":"الكاميرا 📷 (إدخال)"}],"summary":"Input: Keyboard · Mouse · Microphone · Camera — Output: Monitor · Speakers · Printer"}},{"id":"ict-g3.u1.l3","unit_id":"ict-g3.u1","course_id":"ict-g3","position":3,"title":"Mouse and keyboard — الفأرة ولوحة المفاتيح","minutes":8,"intro":{"goals":["أعرف حركات الفأرة","أعرف مفاتيح مهمة في لوحة المفاتيح"],"explain":"Click ضغطة واحدة للاختيار، Double-click ضغطتان سريعتان لفتح ملف أو برنامج، Drag السحب: نضغط ونحرك الشيء ثم نترك. مفاتيح مهمة: Space مسافة بين الكلمات، Enter سطر جديد أو تأكيد، Backspace يمسح الحرف الذي قبل المؤشر، Shift لكتابة حرف كبير.","vocab":[{"w":"Click","ar":"نقرة"},{"w":"Double-click","ar":"نقرتان سريعتان"},{"w":"Drag","ar":"سحب"},{"w":"Space bar","ar":"مفتاح المسافة"},{"w":"Enter","ar":"إدخال / سطر جديد"},{"w":"Backspace","ar":"مسح للخلف"},{"w":"Shift","ar":"لحرف كبير"}],"summary":"Click · Double-click · Drag — Space · Enter · Backspace · Shift"}},{"id":"ict-g3.u1.l4","unit_id":"ict-g3.u1","course_id":"ict-g3","position":4,"title":"Unit 1 review — مراجعة الوحدة الأولى","minutes":8,"intro":{"summary":"راجع: أجزاء الحاسب · Input / Output · الفأرة ولوحة المفاتيح"}},{"id":"ict-g3.u2.l1","unit_id":"ict-g3.u2","course_id":"ict-g3","position":5,"title":"Digital devices — الأجهزة الرقمية","minutes":7,"intro":{"goals":["أتعرف على الأجهزة الرقمية حولي واستخداماتها"],"explain":"الأجهزة الرقمية كثيرة: الحاسب المكتبي Desktop، الحاسب المحمول Laptop، الجهاز اللوحي Tablet، الهاتف الذكي Smartphone، التلفاز الذكي Smart TV، والساعة الذكية Smartwatch. نستخدمها للتعلم والتواصل واللعب والعمل.","vocab":[{"w":"Laptop","ar":"حاسب محمول 💻"},{"w":"Tablet","ar":"جهاز لوحي"},{"w":"Smartphone","ar":"هاتف ذكي 📱"},{"w":"Smart TV","ar":"تلفاز ذكي 📺"},{"w":"Smartwatch","ar":"ساعة ذكية ⌚"}],"summary":"Desktop · Laptop · Tablet · Smartphone · Smart TV · Smartwatch"}},{"id":"ict-g3.u2.l2","unit_id":"ict-g3.u2","course_id":"ict-g3","position":6,"title":"Using devices well — أستخدم الأجهزة بشكل صحيح","minutes":7,"intro":{"goals":["أحافظ على جهازي","أجلس جلسة صحيحة وأحدد وقت الشاشة"],"explain":"نحافظ على الأجهزة: لا نأكل أو نشرب بجانبها، نغلقها بالطريقة الصحيحة (Shut down)، ونمسك الجهاز بيدين. ونحافظ على صحتنا: نجلس وظهرنا مستقيم، والشاشة على بعد مناسب من العين، ونأخذ استراحة، ونلتزم بوقت الشاشة الذي يحدده الوالدان.","vocab":[{"w":"Shut down","ar":"إيقاف التشغيل بشكل صحيح"},{"w":"Screen time","ar":"وقت الشاشة"},{"w":"Break","ar":"استراحة"}],"summary":"لا طعام ولا شراب بجانب الجهاز · Shut down صحيح · ظهر مستقيم · استراحة · وقت محدد"}},{"id":"ict-g3.u2.l3","unit_id":"ict-g3.u2","course_id":"ict-g3","position":7,"title":"Unit 2 review — مراجعة الوحدة الثانية","minutes":7,"intro":{"summary":"راجع: الأجهزة الرقمية · العناية بالجهاز · وقت الشاشة"}},{"id":"ict-g3.u3.l1","unit_id":"ict-g3.u3","course_id":"ict-g3","position":8,"title":"My personal information — معلوماتي الشخصية","minutes":7,"intro":{"goals":["أعرف ما هي المعلومات الشخصية","لا أشاركها مع الغرباء"],"explain":"المعلومات الشخصية Personal information مثل: اسمي الكامل، عنواني، رقم هاتفي، اسم مدرستي، كلمة المرور، صوري. لا أشاركها مع أحد على الإنترنت، وأسأل والديّ قبل أي شيء.","vocab":[{"w":"Personal information","ar":"المعلومات الشخصية"},{"w":"Password","ar":"كلمة المرور (سرّ)"},{"w":"Stranger","ar":"شخص غريب"},{"w":"Trusted adult","ar":"شخص كبير أثق به (أبي، أمي، معلمي)"}],"summary":"لا أشارك: الاسم الكامل · العنوان · الهاتف · المدرسة · كلمة المرور · الصور"}},{"id":"ict-g3.u3.l2","unit_id":"ict-g3.u3","course_id":"ict-g3","position":9,"title":"Be kind online — كن لطيفًا على الإنترنت","minutes":7,"intro":{"goals":["أتصرف بأدب على الإنترنت","أعرف ماذا أفعل مع الرسائل المؤذية والإعلانات المنبثقة"],"explain":"على الإنترنت نكون لطفاء كما في الحقيقة: نكتب كلامًا طيبًا، ولا نسخر من أحد. إذا وصلتنا رسالة مؤذية لا نرد بالمثل، بل نخبر شخصًا كبيرًا. وإذا ظهرت نافذة Pop-up تقول «اضغط هنا لتربح» لا نضغط عليها.","vocab":[{"w":"Kind","ar":"لطيف"},{"w":"Mean message","ar":"رسالة مؤذية"},{"w":"Pop-up","ar":"نافذة منبثقة / إعلان"}],"summary":"أكتب كلامًا طيبًا · لا أرد على الإساءة · أخبر الكبار · لا أضغط على Pop-ups"}},{"id":"ict-g3.u3.l3","unit_id":"ict-g3.u3","course_id":"ict-g3","position":10,"title":"Unit 3 review — مراجعة الوحدة الثالثة","minutes":7,"intro":{"summary":"راجع: المعلومات الشخصية · اللطف على الإنترنت · الشخص الكبير الموثوق"}},{"id":"ict-g3.u4.l1","unit_id":"ict-g3.u4","course_id":"ict-g3","position":11,"title":"Steps in order — الخطوات بالترتيب (Algorithm)","minutes":8,"intro":{"goals":["أعرف أن الخوارزمية Algorithm خطوات مرتبة لحل مشكلة","أرتّب خطوات مهمة يومية"],"explain":"الحاسب لا يفكر وحده؛ ينفّذ الأوامر خطوة خطوة. الخوارزمية Algorithm قائمة خطوات مرتبة لعمل شيء. إذا تغيّر الترتيب قد لا تنجح المهمة: لا نلبس الحذاء قبل الجورب!","vocab":[{"w":"Algorithm","ar":"خوارزمية: خطوات مرتبة"},{"w":"Step","ar":"خطوة"},{"w":"Order / Sequence","ar":"الترتيب / التسلسل"},{"w":"Instruction / Command","ar":"أمر"}],"examples":["غسل اليدين: افتح الصنبور ← ضع الصابون ← افرك يديك ← اشطفهما ← جففهما"],"summary":"Algorithm = خطوات بالترتيب · الترتيب مهم"}},{"id":"ict-g3.u4.l2","unit_id":"ict-g3.u4","course_id":"ict-g3","position":12,"title":"Moving the robot — نحرّك الروبوت","minutes":8,"intro":{"goals":["أعطي أوامر حركة واضحة","أستخدم التكرار Repeat"],"explain":"نستطيع أن نوجّه روبوتًا بأوامر: Move forward (تقدّم خطوة)، Turn left (استدر يسارًا)، Turn right (استدر يمينًا). إذا تكرر نفس الأمر نستخدم Repeat: بدل كتابة «تقدّم» 4 مرات نكتب Repeat 4 → Move forward. وهذا اسمه حلقة تكرار Loop.","vocab":[{"w":"Move forward","ar":"تقدّم للأمام"},{"w":"Turn left","ar":"استدر يسارًا"},{"w":"Turn right","ar":"استدر يمينًا"},{"w":"Repeat / Loop","ar":"كرّر / حلقة تكرار"}],"summary":"Move forward · Turn left · Turn right · Repeat = Loop"}},{"id":"ict-g3.u4.l3","unit_id":"ict-g3.u4","course_id":"ict-g3","position":13,"title":"Find the bug — أجد الخطأ (Debugging)","minutes":8,"intro":{"goals":["أعرف أن الخطأ في البرنامج اسمه Bug","أجد الخطأ وأصلحه"],"explain":"أحيانًا لا يعمل البرنامج كما نريد لأن فيه خطأ Bug: خطوة ناقصة أو في غير مكانها. إيجاد الخطأ وإصلاحه اسمه Debugging. المبرمج الجيد لا يغضب من الأخطاء؛ يجرب ويصلح ويتعلم.","vocab":[{"w":"Bug","ar":"خطأ في البرنامج"},{"w":"Debugging","ar":"إيجاد الخطأ وإصلاحه"},{"w":"Test","ar":"تجربة"}],"summary":"Bug = خطأ · Debugging = أجد الخطأ وأصلحه · أجرّب مرة أخرى"}},{"id":"ict-g3.u4.l4","unit_id":"ict-g3.u4","course_id":"ict-g3","position":14,"title":"Unit 4 review — مراجعة الوحدة الرابعة","minutes":8,"intro":{"summary":"راجع: Algorithm · Repeat / Loop · Bug / Debugging"}},{"id":"fr-g6.u1.l1","unit_id":"fr-g6.u1","course_id":"fr-g6","position":1,"title":"Ma carte d''identité — بطاقتي","minutes":8,"intro":{"goals":["أعرّف بنفسي: الاسم، العمر، البلد، المدينة"],"explain":"لنعرّف بأنفسنا نستخدم: Je m''appelle … (اسمي)، J''ai … ans (عمري)، Je suis égyptien / égyptienne (أنا مصري / مصرية)، J''habite au Caire (أسكن في القاهرة).","vocab":[{"w":"Je m''appelle Omar.","ar":"اسمي عمر.","say":"جُو مابِلْ عمر"},{"w":"J''ai douze ans.","ar":"عمري 12 سنة.","say":"جيه دُوز أون"},{"w":"Je suis égyptien.","ar":"أنا مصري.","say":"جُو سْوِي إيجِپْسْيان"},{"w":"J''habite au Caire.","ar":"أسكن في القاهرة.","say":"جابِيت أُو كِير"},{"w":"Je suis en sixième année du primaire.","ar":"أنا في الصف السادس.","say":"جُو سْوِي أون سِيزْيِيم آنيه دُو پْرِيمِير"}],"examples":["Bonjour ! Je m''appelle Omar. J''ai douze ans. Je suis égyptien."],"summary":"Je m''appelle · J''ai … ans · Je suis égyptien(ne) · J''habite à / au …"}},{"id":"fr-g6.u1.l2","unit_id":"fr-g6.u1","course_id":"fr-g6","position":2,"title":"Le verbe être — فعل «يكون»","minutes":9,"intro":{"goals":["أصرّف فعل être مع كل الضمائر"],"explain":"فعل être يعني «يكون». نستخدمه لنقول من نحن وكيف نحن: Je suis grand. (أنا طويل).","vocab":[{"w":"je suis","ar":"أنا أكون","say":"جُو سْوِي"},{"w":"tu es","ar":"أنتَ / أنتِ","say":"تُو إيه"},{"w":"il / elle est","ar":"هو / هي","say":"إيل / إيل إيه"},{"w":"nous sommes","ar":"نحن","say":"نُو سوم"},{"w":"vous êtes","ar":"أنتم / حضرتك","say":"ڤُو زِيت"},{"w":"ils / elles sont","ar":"هم / هنّ","say":"إيل / إيل سون"}],"summary":"je suis · tu es · il/elle est · nous sommes · vous êtes · ils/elles sont"}},{"id":"fr-g6.u1.l3","unit_id":"fr-g6.u1","course_id":"fr-g6","position":3,"title":"Le verbe avoir — فعل «يملك»","minutes":9,"intro":{"goals":["أصرّف فعل avoir","أستخدمه للعمر: J''ai 12 ans"],"explain":"فعل avoir يعني «يملك / عنده». في الفرنسية نقول العمر بفعل avoir: J''ai douze ans.","vocab":[{"w":"j''ai","ar":"عندي","say":"جيه"},{"w":"tu as","ar":"عندك","say":"تُو آ"},{"w":"il / elle a","ar":"عنده / عندها","say":"إيل / إيل آ"},{"w":"nous avons","ar":"عندنا","say":"نُو زاڤون"},{"w":"vous avez","ar":"عندكم","say":"ڤُو زاڤيه"},{"w":"ils / elles ont","ar":"عندهم","say":"إيل زون"}],"summary":"j''ai · tu as · il/elle a · nous avons · vous avez · ils/elles ont"}},{"id":"fr-g6.u1.l4","unit_id":"fr-g6.u1","course_id":"fr-g6","position":4,"title":"مراجعة الوحدة 1 — Je me présente","minutes":9,"intro":{"summary":"راجع: التعريف بالنفس · être · avoir"}},{"id":"fr-g6.u2.l1","unit_id":"fr-g6.u2","course_id":"fr-g6","position":5,"title":"Quelle heure est-il ? — كم الساعة؟","minutes":9,"intro":{"goals":["أسأل عن الساعة وأجيب بالساعات الكاملة والنصف والربع"],"explain":"نسأل: Quelle heure est-il ? ونجيب: Il est huit heures (الساعة الثامنة). et demie = ونصف، et quart = وربع، moins le quart = إلا ربع.","vocab":[{"w":"Il est huit heures.","ar":"الساعة 8:00","say":"إيل إيه وِي تُور"},{"w":"Il est sept heures et demie.","ar":"الساعة 7:30","say":"إيل إيه سِيت أُور إيه دُومِي"},{"w":"Il est deux heures et quart.","ar":"الساعة 2:15","say":"إيل إيه دُو زُور إيه كار"},{"w":"Il est midi.","ar":"الساعة 12 ظهرًا","say":"إيل إيه مِيدِي"}],"summary":"heures = ساعات · et demie = ونصف · et quart = وربع · midi = الظهر"}},{"id":"fr-g6.u2.l2","unit_id":"fr-g6.u2","course_id":"fr-g6","position":6,"title":"Ma routine — أفعال -er","minutes":10,"intro":{"goals":["أصرّف أفعال -er في المضارع","أتكلم عن يومي"],"explain":"أفعال كثيرة تنتهي بـ -er مثل regarder (يشاهد) وjouer (يلعب) وmanger (يأكل). نحذف -er ونضيف: je -e، tu -es، il/elle -e، nous -ons، vous -ez، ils/elles -ent. مثال: je regarde، tu regardes، il regarde، nous regardons، vous regardez، ils regardent.","vocab":[{"w":"regarder la télé","ar":"يشاهد التلفاز","say":"رُوجارْدِيه لا تيليه"},{"w":"jouer","ar":"يلعب","say":"جُويه"},{"w":"manger","ar":"يأكل","say":"مونْجيه"},{"w":"écouter","ar":"يستمع","say":"إيكُوتيه"},{"w":"travailler","ar":"يعمل / يذاكر","say":"تْراڤايِيه"}],"summary":"-e · -es · -e · -ons · -ez · -ent"}},{"id":"fr-g6.u2.l3","unit_id":"fr-g6.u2","course_id":"fr-g6","position":7,"title":"مراجعة الوحدة 2 — Ma journée","minutes":9,"intro":{"summary":"راجع: Quelle heure est-il ? · تصريف أفعال -er"}},{"id":"fr-g6.u3.l1","unit_id":"fr-g6.u3","course_id":"fr-g6","position":8,"title":"Les matières — المواد الدراسية","minutes":8,"intro":{"goals":["أسمّي المواد الدراسية بالفرنسية"],"vocab":[{"w":"les maths","ar":"الرياضيات","say":"لِيه مات"},{"w":"le français","ar":"اللغة الفرنسية","say":"لُو فْرونْسيه"},{"w":"l''anglais","ar":"اللغة الإنجليزية","say":"لونْجْليه"},{"w":"l''arabe","ar":"اللغة العربية","say":"لارَب"},{"w":"les sciences","ar":"العلوم","say":"لِيه سْيونْس"},{"w":"le sport","ar":"التربية الرياضية","say":"لُو سْپور"},{"w":"le dessin","ar":"الرسم","say":"لُو دِيسان"},{"w":"l''informatique","ar":"الحاسب الآلي","say":"لانْفورماتِيك"}],"explain":"قبل اسم المادة نضع le أو la أو l'' (قبل حرف متحرك) أو les (للجمع).","summary":"les maths · le français · l''anglais · l''arabe · les sciences · le sport · le dessin"}},{"id":"fr-g6.u3.l2","unit_id":"fr-g6.u3","course_id":"fr-g6","position":9,"title":"J''aime / je n''aime pas — أحب / لا أحب","minutes":9,"intro":{"goals":["أعبّر عمّا أحب وما لا أحب","أنفي الجملة بـ ne … pas"],"explain":"J''aime les maths = أحب الرياضيات. Je préfère le dessin = أفضّل الرسم. للنفي نضع ne قبل الفعل وpas بعده: Je n''aime pas le sport. ne تصبح n'' قبل حرف متحرك (n''aime).","vocab":[{"w":"J''aime les sciences.","ar":"أحب العلوم.","say":"جِيم لِيه سْيونْس"},{"w":"Je n''aime pas le sport.","ar":"لا أحب الرياضة.","say":"جُو نِيم پا لُو سْپور"},{"w":"Je préfère l''anglais.","ar":"أفضّل الإنجليزية.","say":"جُو پْريفير لونْجْليه"},{"w":"Ma matière préférée, c''est …","ar":"مادتي المفضلة هي …","say":"ما ماتْيِير پْريفيريه سيه"}],"summary":"J''aime · Je préfère · Je ne … pas"}},{"id":"fr-g6.u3.l3","unit_id":"fr-g6.u3","course_id":"fr-g6","position":10,"title":"Poser des questions — أسأل","minutes":8,"intro":{"goals":["أستخدم كلمات السؤال الأساسية"],"vocab":[{"w":"Qui ?","ar":"من؟","say":"كِي؟"},{"w":"Quoi ? / Qu''est-ce que … ?","ar":"ماذا؟","say":"كْوا؟ / كِسْكُو؟"},{"w":"Où ?","ar":"أين؟","say":"أُو؟"},{"w":"Quand ?","ar":"متى؟","say":"كون؟"},{"w":"Comment ?","ar":"كيف؟","say":"كومون؟"},{"w":"Pourquoi ? — Parce que …","ar":"لماذا؟ — لأن …","say":"پُورْكْوا؟ — پارْسْ كُو"}],"explain":"Pourquoi نسأل بها عن السبب، ونجيب بـ Parce que …","summary":"Qui · Quoi · Où · Quand · Comment · Pourquoi"}},{"id":"fr-g6.u3.l4","unit_id":"fr-g6.u3","course_id":"fr-g6","position":11,"title":"مراجعة الوحدة 3 — À l''école","minutes":9,"intro":{"summary":"راجع: المواد · J''aime / Je préfère · ne … pas · كلمات السؤال"}},{"id":"fr-g6.u4.l1","unit_id":"fr-g6.u4","course_id":"fr-g6","position":12,"title":"Les lieux de la ville — أماكن المدينة","minutes":8,"intro":{"goals":["أسمّي أماكن المدينة"],"vocab":[{"w":"la boulangerie","ar":"المخبز","say":"لا بُولونْجْرِي"},{"w":"la pharmacie","ar":"الصيدلية","say":"لا فارْماسِي"},{"w":"l''hôpital","ar":"المستشفى","say":"لوپِيتال"},{"w":"le parc","ar":"الحديقة","say":"لُو پارْك"},{"w":"le supermarché","ar":"السوبرماركت","say":"لُو سُوپِيرْمارْشيه"},{"w":"la mosquée","ar":"المسجد","say":"لا مُوسْكيه"},{"w":"la gare","ar":"محطة القطار","say":"لا جار"},{"w":"la bibliothèque","ar":"المكتبة (للقراءة)","say":"لا بِيبْلِيُوتِيك"}],"summary":"boulangerie · pharmacie · hôpital · parc · supermarché · mosquée · gare · bibliothèque"}},{"id":"fr-g6.u4.l2","unit_id":"fr-g6.u4","course_id":"fr-g6","position":13,"title":"Où est … ? — حروف الجر المكانية","minutes":9,"intro":{"goals":["أصف مكان شيء: أمام، خلف، بجانب، بين، على، تحت، في"],"vocab":[{"w":"devant","ar":"أمام","say":"دُوڤون"},{"w":"derrière","ar":"خلف","say":"دِيرْيِير"},{"w":"à côté de","ar":"بجانب","say":"آ كوتيه دُو"},{"w":"entre","ar":"بين","say":"أونْتْر"},{"w":"sur","ar":"على","say":"سُور"},{"w":"sous","ar":"تحت","say":"سُو"},{"w":"dans","ar":"في / داخل","say":"دون"}],"explain":"مثال: La pharmacie est à côté de la boulangerie. = الصيدلية بجانب المخبز.","summary":"devant · derrière · à côté de · entre · sur · sous · dans"}},{"id":"fr-g6.u4.l3","unit_id":"fr-g6.u4","course_id":"fr-g6","position":14,"title":"Je vais au parc — فعل aller","minutes":9,"intro":{"goals":["أصرّف فعل aller (يذهب)","أستخدم au / à la / à l''"],"explain":"aller = يذهب: je vais، tu vas، il/elle va، nous allons، vous allez، ils/elles vont. بعده: au + مذكر (au parc)، à la + مؤنث (à la gare)، à l'' + حرف متحرك (à l''école).","vocab":[{"w":"Je vais au parc.","ar":"أذهب إلى الحديقة.","say":"جُو ڤيه أُو پارْك"},{"w":"Tu vas à la boulangerie.","ar":"تذهب إلى المخبز.","say":"تُو ڤا آ لا بُولونْجْرِي"},{"w":"Nous allons à l''école.","ar":"نذهب إلى المدرسة.","say":"نُو زالون آ ليكول"},{"w":"Ils vont au supermarché.","ar":"يذهبون إلى السوبرماركت.","say":"إيل ڤون أُو سُوپِيرْمارْشيه"}],"summary":"je vais · tu vas · il va · nous allons · vous allez · ils vont — au / à la / à l''"}},{"id":"fr-g6.u4.l4","unit_id":"fr-g6.u4","course_id":"fr-g6","position":15,"title":"مراجعة الوحدة 4 — Dans ma ville","minutes":9,"intro":{"summary":"راجع: أماكن المدينة · حروف الجر · aller + au / à la"}},{"id":"fr-g6.u5.l1","unit_id":"fr-g6.u5","course_id":"fr-g6","position":16,"title":"Jouer au / faire du — الرياضة والهوايات","minutes":9,"intro":{"goals":["أتكلم عن هواياتي"],"explain":"مع الألعاب نقول jouer au …: Je joue au football. ومع رياضات أخرى نقول faire du / de la …: Je fais du vélo (أركب الدراجة)، Je fais de la natation (أسبح).","vocab":[{"w":"jouer au football","ar":"يلعب كرة القدم","say":"جُويه أُو فُوتْبول"},{"w":"jouer au basket","ar":"يلعب كرة السلة","say":"جُويه أُو باسْكِيت"},{"w":"faire du vélo","ar":"يركب الدراجة","say":"فِير دُو ڤيلو"},{"w":"faire de la natation","ar":"يمارس السباحة","say":"فِير دُو لا ناتاسْيون"},{"w":"lire","ar":"يقرأ","say":"لِير"},{"w":"dessiner","ar":"يرسم","say":"دِيسِينيه"}],"summary":"jouer au + لعبة · faire du / de la + رياضة"}},{"id":"fr-g6.u5.l2","unit_id":"fr-g6.u5","course_id":"fr-g6","position":17,"title":"Au repas — الطعام","minutes":8,"intro":{"goals":["أسمّي أطعمة وأعبّر عما أحب أن آكل"],"vocab":[{"w":"le pain","ar":"الخبز","say":"لُو پان"},{"w":"le riz","ar":"الأرز","say":"لُو رِي"},{"w":"le poulet","ar":"الدجاج","say":"لُو پُوليه"},{"w":"le poisson","ar":"السمك","say":"لُو پْواسون"},{"w":"les fruits","ar":"الفواكه","say":"لِيه فْرْوِي"},{"w":"l''eau","ar":"الماء","say":"لُو"},{"w":"le petit-déjeuner","ar":"الإفطار","say":"لُو پْتِي دِيجُونيه"},{"w":"le déjeuner / le dîner","ar":"الغداء / العشاء","say":"لُو دِيجُونيه / لُو دِينيه"}],"explain":"J''aime le poisson = أحب السمك. Je mange du riz = آكل (بعض) الأرز.","summary":"pain · riz · poulet · poisson · fruits · eau"}},{"id":"fr-g6.u5.l3","unit_id":"fr-g6.u5","course_id":"fr-g6","position":18,"title":"مراجعة الوحدة 5 — Mes loisirs","minutes":9,"intro":{"summary":"راجع: jouer au · faire du / de la · الطعام"}},{"id":"ict-g6.u1.l1","unit_id":"ict-g6.u1","course_id":"ict-g6","position":1,"title":"Computer Networks — شبكات الحاسب","minutes":9,"intro":{"goals":["أعرف ما هي شبكة الحاسب وفوائدها","أفرّق بين LAN وWAN","أعرف دور الراوتر Router"],"explain":"الشبكة (Network) هي جهازان أو أكثر متصلة ببعضها لتتبادل البيانات وتتشارك الموارد مثل الطابعة والملفات والإنترنت. الشبكة المحلية LAN تغطي مكانًا صغيرًا مثل البيت أو المدرسة، والشبكة الواسعة WAN تغطي مدنًا ودولًا. والإنترنت أكبر شبكة في العالم. يمكن أن يكون الاتصال سلكيًا (كابل) أو لاسلكيًا (Wi-Fi).","vocab":[{"w":"Network","ar":"شبكة: أجهزة متصلة تتبادل البيانات"},{"w":"LAN (Local Area Network)","ar":"شبكة محلية في مكان صغير"},{"w":"WAN (Wide Area Network)","ar":"شبكة واسعة بين مدن أو دول"},{"w":"Router","ar":"الراوتر: يوصل الأجهزة بالشبكة وبالإنترنت"},{"w":"Wi-Fi","ar":"اتصال لاسلكي بالشبكة"},{"w":"Server","ar":"الخادم: جهاز يقدّم خدمات وملفات لأجهزة أخرى"}],"examples":["أجهزة معمل الكمبيوتر في المدرسة المتصلة بطابعة واحدة = LAN","شبكة البنوك التي تربط فروعها في كل المحافظات = WAN"],"activity":"اكتب أسماء 3 أجهزة في بيتك متصلة بالـ Wi-Fi.","summary":"Network = أجهزة متصلة · LAN صغيرة · WAN واسعة · الإنترنت أكبر شبكة · Router يوصلنا بالإنترنت"}},{"id":"ict-g6.u1.l2","unit_id":"ict-g6.u1","course_id":"ict-g6","position":2,"title":"Future Technology & Technology for People with Special Needs — تكنولوجيا المستقبل وذوو الهمم","minutes":9,"intro":{"goals":["أتعرف على أمثلة لتكنولوجيا المستقبل","أعرف كيف تساعد التكنولوجيا ذوي الهمم"],"explain":"من تكنولوجيا المستقبل: الذكاء الاصطناعي (AI) الذي يجعل الأجهزة تتعلم وتتخذ قرارات، والروبوتات، والطباعة ثلاثية الأبعاد 3D Printing، والواقع الافتراضي VR، والمنازل الذكية Smart Homes. والتكنولوجيا المساعدة تساعد ذوي الهمم: قارئ الشاشة Screen Reader يقرأ النص بصوت عالٍ لضعاف البصر، وتحويل الكلام إلى نص Speech-to-text يساعد من لا يستطيع الكتابة، وشاشة برايل Braille display للمكفوفين.","vocab":[{"w":"Artificial Intelligence (AI)","ar":"الذكاء الاصطناعي"},{"w":"Robot","ar":"روبوت: آلة تنفذ مهامًا بالبرمجة"},{"w":"Virtual Reality (VR)","ar":"الواقع الافتراضي"},{"w":"3D printer","ar":"طابعة ثلاثية الأبعاد تصنع مجسمات"},{"w":"Screen reader","ar":"قارئ الشاشة لضعاف البصر"},{"w":"Speech-to-text","ar":"تحويل الكلام إلى نص مكتوب"}],"examples":["المساعد الصوتي في الهاتف يفهم كلامك = AI","نظارة VR تجعلك تشعر أنك داخل متحف"],"summary":"AI · Robots · VR · 3D printing · Smart homes — والتكنولوجيا المساعدة: Screen reader · Speech-to-text · Braille display"}},{"id":"ict-g6.u1.l3","unit_id":"ict-g6.u1","course_id":"ict-g6","position":3,"title":"Digital Search Tools — أدوات البحث الرقمي","minutes":9,"intro":{"goals":["أستخدم محرك البحث بكلمات مفتاحية مناسبة","أتأكد من صحة المعلومة ومصدرها"],"explain":"محرك البحث Search Engine (مثل Google وBing) يبحث في مواقع الإنترنت. نكتب كلمات مفتاحية Keywords قصيرة ومحددة بدل جملة طويلة. وضع الكلمات بين علامتي تنصيص \"...\" يبحث عن العبارة نفسها بالضبط. نستخدم الفلاتر (صور، أخبار، فيديو) لتضييق النتائج، ونتأكد أن المصدر موثوق ونقارن أكثر من مصدر.","vocab":[{"w":"Search engine","ar":"محرك البحث"},{"w":"Keywords","ar":"الكلمات المفتاحية"},{"w":"Results","ar":"نتائج البحث"},{"w":"Reliable source","ar":"مصدر موثوق"},{"w":"Filter","ar":"تصفية النتائج (صور، أخبار…)"}],"examples":["بدل «ما هو أطول نهر في قارة أفريقيا؟» اكتب: longest river Africa"],"activity":"اكتب 3 كلمات مفتاحية للبحث عن «فوائد الطاقة الشمسية».","summary":"Search engine + Keywords قصيرة · \"...\" للعبارة الدقيقة · Filters · قارن المصادر"}},{"id":"ict-g6.u1.l4","unit_id":"ict-g6.u1","course_id":"ict-g6","position":4,"title":"How Operating Systems Work — كيف تعمل أنظمة التشغيل","minutes":9,"intro":{"goals":["أعرف وظيفة نظام التشغيل","أذكر أمثلة لأنظمة التشغيل"],"explain":"نظام التشغيل Operating System (OS) هو البرنامج الأساسي الذي يدير الجهاز: يشغّل البرامج، وينظم الملفات والمجلدات، ويتحكم في المكونات (الذاكرة، الشاشة، لوحة المفاتيح)، ويوفر واجهة نتعامل بها مع الجهاز. أمثلة: Windows وmacOS وLinux للحواسب، وAndroid وiOS للهواتف. عند تشغيل الجهاز (Booting) يتم تحميل نظام التشغيل قبل باقي البرامج.","vocab":[{"w":"Operating System (OS)","ar":"نظام التشغيل"},{"w":"Hardware","ar":"المكونات المادية"},{"w":"Software","ar":"البرامج"},{"w":"Booting","ar":"إقلاع / بدء تشغيل الجهاز"},{"w":"File / Folder","ar":"ملف / مجلد"},{"w":"Interface","ar":"الواجهة التي نتعامل بها مع الجهاز"}],"summary":"OS يدير الجهاز والبرامج والملفات · Windows / macOS / Linux / Android / iOS"}},{"id":"ict-g6.u1.l5","unit_id":"ict-g6.u1","course_id":"ict-g6","position":5,"title":"I''m a Web Designer — أنا مصمم مواقع","minutes":9,"intro":{"goals":["أعرف الفرق بين الموقع وصفحة الويب","أتعرف على HTML والرابط Link والعنوان URL"],"explain":"الموقع Website مجموعة صفحات ويب Web pages مرتبطة ببعضها. الصفحة الأولى اسمها Home page. لكل موقع عنوان URL مثل www.example.com، ونفتحه بمتصفح Browser. تُكتب صفحات الويب بلغة HTML، والروابط Links تنقلنا من صفحة لأخرى. المصمم الجيد يجعل الموقع واضحًا وسهل الاستخدام ومناسبًا للهاتف والكمبيوتر.","vocab":[{"w":"Website","ar":"موقع إلكتروني"},{"w":"Web page","ar":"صفحة ويب"},{"w":"Home page","ar":"الصفحة الرئيسية"},{"w":"URL","ar":"عنوان الموقع"},{"w":"Browser","ar":"المتصفح (Chrome, Safari, Edge)"},{"w":"HTML","ar":"لغة كتابة صفحات الويب"},{"w":"Link","ar":"رابط ينقلك لصفحة أخرى"}],"summary":"Website = صفحات · Home page · URL · Browser · HTML · Links"}},{"id":"ict-g6.u1.l6","unit_id":"ict-g6.u1","course_id":"ict-g6","position":6,"title":"Unit 1 review — مراجعة الوحدة الأولى","minutes":10,"intro":{"summary":"راجع: Networks · Future technology · Search tools · Operating systems · Web design"}},{"id":"ict-g6.u2.l1","unit_id":"ict-g6.u2","course_id":"ict-g6","position":7,"title":"The World of Video Games: Fun and Safety — ألعاب الفيديو بأمان","minutes":9,"intro":{"goals":["أختار ألعابًا مناسبة لعمري","ألعب بأمان وبوقت محدد"],"explain":"ألعاب الفيديو ممتعة وتنمّي التفكير، لكن لها قواعد أمان: نختار ألعابًا مناسبة لعمرنا (تصنيف العمر Age rating)، ونحدد وقت اللعب ونأخذ استراحة، ولا نشارك معلوماتنا الشخصية مع لاعبين غرباء، ولا نشتري شيئًا داخل اللعبة (In-game purchases) دون إذن الوالدين، ونبلغ شخصًا كبيرًا إذا ضايقنا أحد في اللعبة.","vocab":[{"w":"Age rating","ar":"تصنيف العمر المناسب للعبة"},{"w":"Screen time","ar":"وقت استخدام الشاشة"},{"w":"In-game purchase","ar":"الشراء داخل اللعبة"},{"w":"Personal information","ar":"المعلومات الشخصية (الاسم الكامل، العنوان، رقم الهاتف…)"},{"w":"Report / Block","ar":"الإبلاغ / الحظر"}],"summary":"لعبة مناسبة لعمري · وقت محدد · لا معلومات شخصية · لا شراء بدون إذن · أبلّغ الكبار"}},{"id":"ict-g6.u2.l2","unit_id":"ict-g6.u2","course_id":"ict-g6","position":8,"title":"Protecting My Digital Data — حماية بياناتي الرقمية","minutes":9,"intro":{"goals":["أنشئ كلمة مرور قوية","أحمي بياناتي بالنسخ الاحتياطي والتحديث"],"explain":"البيانات الرقمية مثل الصور والملفات والحسابات يجب حمايتها. كلمة المرور القوية Strong password طويلة (8 رموز أو أكثر) وتجمع حروفًا كبيرة وصغيرة وأرقامًا ورموزًا، ولا تكون اسمك أو تاريخ ميلادك، ولا نشاركها مع أحد إلا الوالدين. النسخ الاحتياطي Backup يحفظ نسخة من ملفاتك، وبرنامج مكافحة الفيروسات Antivirus وتحديث البرامج Updates يحميان الجهاز.","vocab":[{"w":"Strong password","ar":"كلمة مرور قوية"},{"w":"Backup","ar":"نسخة احتياطية"},{"w":"Antivirus","ar":"برنامج مكافحة الفيروسات"},{"w":"Update","ar":"تحديث البرنامج"},{"w":"Two-step verification","ar":"التحقق بخطوتين"}],"summary":"كلمة مرور قوية وسرية · Backup · Antivirus · Updates · التحقق بخطوتين"}},{"id":"ict-g6.u2.l3","unit_id":"ict-g6.u2","course_id":"ict-g6","position":9,"title":"Be a Cyber Security Hero — كن بطل الأمن السيبراني","minutes":9,"intro":{"goals":["أتعرف على الفيروسات والرسائل المزيفة (Phishing)","أعرف ماذا أفعل عند الشك"],"explain":"الأمن السيبراني Cyber security هو حماية الأجهزة والبيانات من الهجمات. البرامج الضارة Malware (مثل الفيروسات) قد تدخل من ملفات أو روابط مجهولة. التصيد Phishing رسالة مزيفة تطلب كلمة المرور أو معلومات شخصية أو تقول «لقد ربحت جائزة!». البطل لا يضغط على روابط مجهولة، ولا يفتح ملفات من غرباء، ويخبر شخصًا كبيرًا.","vocab":[{"w":"Cyber security","ar":"الأمن السيبراني"},{"w":"Malware / Virus","ar":"برنامج ضار / فيروس"},{"w":"Phishing","ar":"التصيد: رسالة مزيفة لسرقة البيانات"},{"w":"Hacker","ar":"مخترق"},{"w":"Suspicious link","ar":"رابط مشبوه"}],"summary":"لا روابط مجهولة · لا ملفات من غرباء · لا أعطي كلمة المرور · أخبر الكبار"}},{"id":"ict-g6.u2.l4","unit_id":"ict-g6.u2","course_id":"ict-g6","position":10,"title":"Online Financial Trading — البيع والشراء والدفع الإلكتروني","minutes":9,"intro":{"goals":["أعرف معنى التجارة الإلكترونية والدفع الإلكتروني","أعرف قواعد الأمان عند الشراء أونلاين"],"explain":"التجارة الإلكترونية E-commerce هي البيع والشراء عبر الإنترنت. ونستطيع الدفع إلكترونيًا بالبطاقة البنكية أو المحفظة الإلكترونية E-wallet. قواعد الأمان: الشراء يكون مع ولي الأمر وبإذنه، ومن مواقع معروفة وموثوقة يبدأ عنوانها بـ https وبجانبه رمز القفل 🔒 — لكن https والقفل يعنيان أن الاتصال مشفّر فقط، ولا يضمنان أن الموقع صادق، ولا نشارك بيانات البطاقة أو كلمات المرور أبدًا، ونحذر من العروض التي تبدو أجمل من الحقيقة.","vocab":[{"w":"E-commerce","ar":"التجارة الإلكترونية"},{"w":"Online payment","ar":"الدفع الإلكتروني"},{"w":"E-wallet","ar":"المحفظة الإلكترونية"},{"w":"https / 🔒","ar":"علامة الاتصال الآمن بالموقع"},{"w":"Scam","ar":"احتيال"}],"summary":"E-commerce · Online payment · https 🔒 · بإذن الوالدين · لا أشارك بيانات البطاقة"}},{"id":"ict-g6.u2.l5","unit_id":"ict-g6.u2","course_id":"ict-g6","position":11,"title":"Cloud Computing & Cloud Storage — الحوسبة السحابية","minutes":9,"intro":{"goals":["أعرف معنى الحوسبة السحابية","أذكر أمثلة لتطبيقات التخزين السحابي ومزاياها"],"explain":"الحوسبة السحابية Cloud computing هي استخدام برامج ومساحات تخزين موجودة على خوادم عبر الإنترنت بدل جهازك. التخزين السحابي Cloud storage مثل Google Drive وOneDrive وiCloud وDropbox يحفظ ملفاتك أونلاين. المزايا: الوصول لملفاتك من أي جهاز، ومشاركتها بسهولة، وعدم ضياعها إذا تلف الجهاز. ونحتاج اتصالًا بالإنترنت وكلمة مرور قوية.","vocab":[{"w":"Cloud computing","ar":"الحوسبة السحابية"},{"w":"Cloud storage","ar":"التخزين السحابي"},{"w":"Upload","ar":"رفع ملف إلى السحابة"},{"w":"Download","ar":"تنزيل ملف إلى جهازك"},{"w":"Share","ar":"مشاركة"}],"summary":"Cloud = خوادم عبر الإنترنت · Google Drive / OneDrive / iCloud · من أي جهاز · يحتاج إنترنت"}},{"id":"ict-g6.u2.l6","un