ls a new phone for 10 pounds only! This may be:","hint":null,"payload":{"options":["Normal","A scam","An update","A network"]},"answer_key":{"index":1},"correct_text":"A scam","explanation":"العرض الذي يبدو أجمل من الحقيقة قد يكون احتيالًا.","lesson_id":"ict-g6.u2.l4","position":4},{"id":"ict-g6.u2.l4.q5","type":"true_false","skill":"ict6.money","prompt":"You can send your parent''s card number to anyone who asks online.","hint":null,"payload":{},"answer_key":{"value":false},"correct_text":"False","explanation":null,"lesson_id":"ict-g6.u2.l4","position":5},{"id":"ict-g6.u2.l5.q1","type":"multiple_choice","skill":"ict6.cloud","prompt":"Which is a cloud storage app?","hint":null,"payload":{"options":["Calculator","Paint","Keyboard","Google Drive"]},"answer_key":{"index":3},"correct_text":"Google Drive","explanation":null,"lesson_id":"ict-g6.u2.l5","position":1},{"id":"ict-g6.u2.l5.q2","type":"multiple_choice","skill":"ict6.cloud","prompt":"One advantage of cloud storage:","hint":null,"payload":{"options":["No need for Internet ever","Open your files from any device","Makes files disappear","Breaks the computer"]},"answer_key":{"index":1},"correct_text":"Open your files from any device","explanation":null,"lesson_id":"ict-g6.u2.l5","position":2},{"id":"ict-g6.u2.l5.q3","type":"multiple_choice","skill":"ict6.cloud","prompt":"Sending a file from your device to the cloud is:","hint":null,"payload":{"options":["Print","Delete","Upload","Download"]},"answer_key":{"index":2},"correct_text":"Upload","explanation":null,"lesson_id":"ict-g6.u2.l5","position":3},{"id":"ict-g6.u2.l5.q4","type":"true_false","skill":"ict6.cloud","prompt":"You usually need an Internet connection to use the cloud.","hint":null,"payload":{},"answer_key":{"value":true},"correct_text":"True","explanation":null,"lesson_id":"ict-g6.u2.l5","position":4},{"id":"ict-g6.u2.l5.q5","type":"matching","skill":"ict6.cloud","prompt":"Match","hint":null,"payload":{"left":["Upload","Download","Share"],"right":["Device → cloud","Let others see the file","Cloud → device"]},"answer_key":{"pairs":3,"map":{"0":0,"1":2,"2":1}},"correct_text":"Upload = Device → cloud, Download = Cloud → device, Share = Let others see the file","explanation":null,"lesson_id":"ict-g6.u2.l5","position":5},{"id":"ict-g6.u2.l6.q1","type":"multiple_choice","skill":"ict6.data","prompt":"Which is a strong password?","hint":null,"payload":{"options":["omar2014","S@fe2026Home!","11111111","abc"]},"answer_key":{"index":1},"correct_text":"S@fe2026Home!","explanation":null,"lesson_id":"ict-g6.u2.l6","position":1},{"id":"ict-g6.u2.l6.q2","type":"multiple_choice","skill":"ict6.cyber","prompt":"An email asks for your password to \"fix your account\". You should:","hint":null,"payload":{"options":["Send the password","Forward it to friends","Not reply and tell an adult","Click every link"]},"answer_key":{"index":2},"correct_text":"Not reply and tell an adult","explanation":null,"lesson_id":"ict-g6.u2.l6","position":2},{"id":"ict-g6.u2.l6.q3","type":"multiple_choice","skill":"ict6.games","prompt":"Good gaming habit:","hint":null,"payload":{"options":["Buy items secretly","Play all night","Set a time limit","Talk to strangers about your school"]},"answer_key":{"index":2},"correct_text":"Set a time limit","explanation":null,"lesson_id":"ict-g6.u2.l6","position":3},{"id":"ict-g6.u2.l6.q4","type":"multiple_choice","skill":"ict6.money","prompt":"The padlock 🔒 next to a website address means:","hint":null,"payload":{"options":["The site is a game","No internet","The connection is secure","The site is closed"]},"answer_key":{"index":2},"correct_text":"The connection is secure","explanation":null,"lesson_id":"ict-g6.u2.l6","position":4},{"id":"ict-g6.u2.l6.q5","type":"multiple_choice","skill":"ict6.cloud","prompt":"OneDrive and iCloud are examples of:","hint":null,"payload":{"options":["Viruses","Cloud storage","Operating systems","Search engines"]},"answer_key":{"index":1},"correct_text":"Cloud storage","explanation":null,"lesson_id":"ict-g6.u2.l6","position":5},{"id":"ict-g6.u2.l6.q6","type":"true_false","skill":"ict6.data","prompt":"A backup protects your files if your device is lost.","hint":null,"payload":{},"answer_key":{"value":true},"correct_text":"True","explanation":null,"lesson_id":"ict-g6.u2.l6","position":6},{"id":"ict-g6.u2.l6.q7","type":"matching","skill":"ict6.terms","prompt":"Match","hint":null,"payload":{"left":["Phishing","Malware","E-commerce"],"right":["Harmful program","Fake message to steal data","Buying online"]},"answer_key":{"pairs":3,"map":{"0":1,"1":0,"2":2}},"correct_text":"Phishing = Fake message to steal data, Malware = Harmful program, E-commerce = Buying online","explanation":null,"lesson_id":"ict-g6.u2.l6","position":7}]'::jsonb)
    as x(id text, lesson_id text, position smallint, type text, skill text, prompt text, hint text,
         payload jsonb, answer_key jsonb, correct_text text, explanation text)
on conflict (id) do update set lesson_id = excluded.lesson_id, position = excluded.position, type = excluded.type,
  skill = excluded.skill, prompt = excluded.prompt, hint = excluded.hint, payload = excluded.payload,
  answer_key = excluded.answer_key, correct_text = excluded.correct_text, explanation = excluded.explanation, archived = false;
update public.questions set archived = true where position > 1000 and lesson_id in (select id from public.lessons where course_id in ('fr-g3', 'ict-g3', 'fr-g6', 'ict-g6'));

-- ---------------------------------------------------------------- per-course progress (parent report)
-- One row per course of the child: lessons done (or known from the placement test) of all lessons,
-- score of the finished lessons (best attempt of each), last activity, the next lesson,
-- strong / weak skills in this course (last 60 days, 3+ answers) and the items to review
-- (questions whose LAST answer was wrong, newest first).
create or replace function app.course_progress(p_profile uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(x.j order by x.pos, x.id), '[]'::jsonb) from (
    select c.position pos, c.id, jsonb_build_object(
      'id', c.id, 'title', c.title, 'subject', c.subject, 'source_kind', c.source_kind,
      'lessons_total', (select count(*) from public.lessons l where l.course_id = c.id and not l.archived),
      'lessons_done', (select count(*) from public.lessons l
                        where l.course_id = c.id and not l.archived
                          and (app.lesson_done(p_profile, l.id) or l.position <= app.placed_position(p_profile, c.id))),
      'score', (select case when sum(b.total) > 0 then round(sum(b.correct)::numeric / sum(b.total), 3) end
                  from (select distinct on (a.lesson_id) a.correct, a.total
                          from public.lesson_attempts a join public.lessons l on l.id = a.lesson_id
                         where a.profile_id = p_profile and l.course_id = c.id and a.finished_at is not null and a.total > 0
                         order by a.lesson_id, a.correct::numeric / a.total desc) b),
      'tests', (select coalesce(jsonb_agg(jsonb_build_object('lesson', t.title, 'correct', t.correct, 'total', t.total,
                                                             'finished_at', t.finished_at) order by t.finished_at desc), '[]'::jsonb)
                  from (select l.title, a.correct, a.total, a.finished_at
                          from public.lesson_attempts a join public.lessons l on l.id = a.lesson_id
                         where a.profile_id = p_profile and l.course_id = c.id and a.finished_at is not null
                         order by a.finished_at desc limit 5) t),
      'last_activity', (select max(greatest(a.started_at, coalesce(a.finished_at, a.started_at)))
                          from public.lesson_attempts a join public.lessons l on l.id = a.lesson_id
                         where a.profile_id = p_profile and l.course_id = c.id),
      'next_lesson', (select l.title from public.lessons l
                       where l.course_id = c.id and not l.archived
                         and not app.lesson_done(p_profile, l.id) and l.position > app.placed_position(p_profile, c.id)
                       order by l.position limit 1),
      'strong', (select coalesce(jsonb_agg(s.name order by s.acc desc), '[]'::jsonb) from (
                   select sk.name, count(*) filter (where an.is_correct)::numeric / count(*) acc
                     from public.answers an
                     join public.lesson_attempts a on a.id = an.attempt_id
                     join public.questions q on q.id = an.question_id
                     join public.lessons l on l.id = q.lesson_id
                     join public.skills sk on sk.code = q.skill
                    where a.profile_id = p_profile and l.course_id = c.id and an.answered_at > now() - interval '60 days'
                    group by sk.name having count(*) >= 3
                       and count(*) filter (where an.is_correct)::numeric / count(*) >= 0.85) s),
      'weak', (select coalesce(jsonb_agg(s.name order by s.acc), '[]'::jsonb) from (
                 select sk.name, count(*) filter (where an.is_correct)::numeric / count(*) acc
                   from public.answers an
                   join public.lesson_attempts a on a.id = an.attempt_id
                   join public.questions q on q.id = an.question_id
                   join public.lessons l on l.id = q.lesson_id
                   join public.skills sk on sk.code = q.skill
                  where a.profile_id = p_profile and l.course_id = c.id and an.answered_at > now() - interval '60 days'
                  group by sk.name having count(*) >= 3
                     and count(*) filter (where an.is_correct)::numeric / count(*) < 0.6) s),
      'to_review', (select coalesce(jsonb_agg(r.item order by r.at desc), '[]'::jsonb) from (
                      select left(case when q.payload ? 'audio' then (q.payload ->> 'audio') || ' = ' || q.correct_text
                                       else q.prompt || ' → ' || q.correct_text end, 90) item, z.at
                        from (select distinct on (an.question_id) an.question_id, an.is_correct, an.answered_at at
                                from public.answers an join public.lesson_attempts a on a.id = an.attempt_id
                               where a.profile_id = p_profile
                               order by an.question_id, an.answered_at desc) z
                        join public.questions q on q.id = z.question_id
                        join public.lessons l on l.id = q.lesson_id
                       where l.course_id = c.id and not z.is_correct
                       order by z.at desc limit 6) r)
    ) j
    from app.courses_for(p_profile) c) x
$$;

revoke all on function app.course_progress(uuid) from public, anon;

-- ---------------------------------------------------------------- lesson explanation
-- The explanation of a lesson of one of the profile's courses (null when the lesson has none),
-- with the course's speech language for the 🔊 buttons.
create or replace function public.lesson_intro(p_profile uuid, p_lesson text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v jsonb;
begin
  perform app.require_profile(p_profile);
  select jsonb_build_object('intro', l.intro, 'speech_lang', c.speech_lang, 'source_kind', c.source_kind,
                            'source_note', c.source_note)
    into v
    from public.lessons l join app.courses_for(p_profile) c on c.id = l.course_id
   where l.id = p_lesson and not l.archived;
  if v is null then perform app.fail('not_found'); end if;
  return v;
end $$;

revoke all on function public.lesson_intro(uuid, text) from public, anon;
grant execute on function public.lesson_intro(uuid, text) to authenticated;

-- course_map(): as in 20261008000011_phase6_daily_plan.sql, plus the course's source label and speech language.
create or replace function public.course_map(p_profile uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform app.require_profile(p_profile);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', c.id, 'subject', c.subject, 'title', c.title, 'level_label', c.level_label,
             'source_kind', c.source_kind, 'source_note', c.source_note, 'edition', c.edition,
             'speech_lang', c.speech_lang,
             'units', (
               select coalesce(jsonb_agg(jsonb_build_object(
                        'id', u.id, 'title', u.title,
                        'lessons', (
                          select coalesce(jsonb_agg(jsonb_build_object(
                                   'id', l.id, 'title', l.title, 'minutes', l.minutes,
                                   'status', case
                                     when app.lesson_done(p_profile, l.id) then 'done'
                                     when exists (select 1 from public.lesson_attempts a
                                                   join public.answers an on an.attempt_id = a.id
                                                  where a.profile_id = p_profile and a.lesson_id = l.id
                                                    and a.finished_at is null) then 'in_progress'
                                     when l.position <= app.placed_position(p_profile, c.id) then 'placed'
                                     when not app.lesson_unlocked(p_profile, l.id) then 'locked'
                                     else 'available' end)
                                 order by l.position), '[]'::jsonb)
                            from public.lessons l where l.unit_id = u.id and not l.archived)
                      ) order by u.position), '[]'::jsonb)
                 from public.units u where u.course_id = c.id and not u.archived)
           ) order by c.position, c.id)
      from app.courses_for(p_profile) c), '[]'::jsonb);
end $$;

-- profile_report(): as in 20260926000002_phase4_learning.sql, plus per-course progress ('courses').
create or replace function public.profile_report(p_profile uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  tz    text;
  today date;
  v_goal int;
  r     jsonb := '{}'::jsonb;
  days  int;
begin
  if not app.i_am_parent() then perform app.fail('parent_only'); end if;
  perform app.require_profile(p_profile);
  tz := app.profile_tz(p_profile);
  today := (now() at time zone tz)::date;
  select daily_minutes_goal into v_goal from public.profiles where id = p_profile;

  -- minutes per day, last 7 days, oldest first
  r := r || jsonb_build_object('minutes_by_day', (
    select jsonb_agg(ceil(coalesce((
             select sum(app.attempt_minutes(a)) from public.lesson_attempts a
              where a.profile_id = p_profile and a.finished_at is not null
                and (a.finished_at at time zone tz)::date = d), 0))::int order by d)
      from generate_series(today - 6, today, interval '1 day') g(dd), lateral (select g.dd::date d) x));

  -- totals for today / 7 days / 30 days
  foreach days in array array[1, 7, 30] loop
    r := r || jsonb_build_object('last_' || days, (
      select jsonb_build_object(
               'minutes', ceil(coalesce((select sum(app.attempt_minutes(a)) from public.lesson_attempts a
                                          where a.profile_id = p_profile and a.finished_at is not null
                                            and (a.finished_at at time zone tz)::date > today - days), 0))::int,
               'questions', count(*),
               'correct', count(*) filter (where an.is_correct),
               'accuracy', case when count(*) = 0 then null
                                else round(count(*) filter (where an.is_correct)::numeric / count(*), 3) end)
        from public.answers an join public.lesson_attempts a on a.id = an.attempt_id
       where a.profile_id = p_profile and (an.answered_at at time zone tz)::date > today - days));
  end loop;

  r := r || jsonb_build_object(
    'daily_goal', v_goal,
    'streak_days', app.streak(p_profile),
    'history', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'lesson', h.title, 'correct', h.correct, 'total', h.total, 'finished_at', h.finished_at)
             order by h.finished_at desc), '[]'::jsonb)
        from (select l.title, a.correct, a.total, a.finished_at
                from public.lesson_attempts a join public.lessons l on l.id = a.lesson_id
               where a.profile_id = p_profile and a.finished_at is not null
               order by a.finished_at desc limit 8) h),
    'skills', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'code', s.skill, 'name', sk.name, 'answers', s.n, 'accuracy', round(s.ok::numeric / s.n, 3))
             order by s.ok::numeric / s.n), '[]'::jsonb)
        from (select q.skill, count(*) n, count(*) filter (where an.is_correct) ok
                from public.answers an
                join public.lesson_attempts a on a.id = an.attempt_id
                join public.questions q on q.id = an.question_id
               where a.profile_id = p_profile and an.answered_at > now() - interval '30 days'
               group by q.skill) s
        join public.skills sk on sk.code = s.skill),
    'to_review', (
      select coalesce(jsonb_agg(distinct sk.name), '[]'::jsonb)
        from public.answers an
        join public.lesson_attempts a on a.id = an.attempt_id
        join public.questions q on q.id = an.question_id
        join public.skills sk on sk.code = q.skill
       where a.profile_id = p_profile and not an.is_correct and an.answered_at > now() - interval '7 days'));
  r := r || jsonb_build_object('courses', app.course_progress(p_profile));
  return r;
end $$;

-- cms_list_courses(): as in 20260926000004_phase5_cms.sql, plus the source label.
create or replace function public.cms_list_courses() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform app.require_editor();
  return coalesce((
    select jsonb_agg(x order by x ->> 'position', x ->> 'id') from (
      select jsonb_build_object(
               'id', coalesce(c.id, d.course_id),
               'title', coalesce(d.doc ->> 'title', c.title),
               'subject', coalesce(d.doc ->> 'subject', c.subject),
               'audience', coalesce(d.doc ->> 'audience', c.audience),
               'source_kind', c.source_kind, 'source_note', c.source_note, 'edition', c.edition,
               'position', lpad(coalesce(d.doc ->> 'position', c.position::text, '99'), 4, '0'),
               'live', c.id is not null,
               'published', coalesce(c.published, false),
               'has_draft', d.course_id is not null,
               'draft_updated_at', d.updated_at,
               'version', (select max(v.version) from public.content_versions v where v.course_id = coalesce(c.id, d.course_id)),
               'lessons', (select count(*) from public.lessons l where l.course_id = c.id and not l.archived),
               'questions', (select count(*) from public.questions q join public.lessons l on l.id = q.lesson_id
                              where l.course_id = c.id and not l.archived and not q.archived)) x
        from public.courses c full join public.content_drafts d on d.course_id = c.id) s), '[]'::jsonb);
end $$;

notify pgrst, 'reload schema';
commit;
